import {P} from './palette.js';
import {oval,line,shape,shadow,face} from './shapes.js';
import {blink} from './animation.js';
export function drawBoss(c,z,x,y,time,o={}){const t=time+(z.uid||0),prep=z.chargeState==='telegraph',charge=z.chargeState==='charging',walk=o.moving===false?0:Math.sin(t*(charge?19:3.8));c.save();c.translate(x,y);shadow(c,0,29,charge?39:32);if(o.death){c.globalAlpha*=1-o.death;c.translate(0,o.death*15);c.rotate(o.death*.9)}if(z.bossId==='collector'){const stealing=z.stealState==='telegraph';c.rotate(-.08+walk*.02);oval(c,-18,-2,16,24,P.bark);shape(c,[[-28,-19],[-13,-24],[-7,16],[-29,15]],P.wood);line(c,[[-17,-24],[-7,-22],[-6,12]],P.gold,4);for(const side of [-1,1])line(c,[[side*7,8],[side*9+walk*3,28]],P.clothDark,7);oval(c,0,-5,13,23,P.clothDark);oval(c,0,-33,12,15,P.skin);face(c,0,-35,{blink:blink(t,z.uid),angry:stealing});line(c,[[10,-12],[stealing?31:22,stealing?-15:-3],[stealing?38:15,stealing?-11:9]],P.skin,7);oval(c,-20,-4,7,8,P.sun);for(let i=0;i<Math.min(4,z.stolenStacks||0);i++){const a=t*.8+i*1.57;oval(c,-19+Math.cos(a)*12,-4+Math.sin(a)*17,3,3,P.sun)}if(stealing){c.globalAlpha=.35+.15*Math.sin(t*15);line(c,[[35,-12],[53+Math.sin(t*8)*3,-12]],P.sun,3)}c.restore();return}if(z.bossId==='foreman'){const command=z.commandState==='telegraph';for(const side of [-1,1])line(c,[[side*8,9],[side*9+walk*2,28]],P.clothDark,9);shape(c,[[-18,-18],[15,-18],[19,15],[-19,15]],P.boss);line(c,[[-10,-14],[-8,13]],P.cream,4);line(c,[[9,-14],[9,13]],P.cream,4);oval(c,0,-31,13,14,P.skin);face(c,0,-33,{angry:true});oval(c,0,-43,17,6,P.gold);line(c,[[16,-12],[28,command?-32:-25],[34,command?-45:-38]],P.skin,8);shape(c,[[34,-43],[48,-39],[34,-30]],P.damage);oval(c,-14,-29,4,3,P.gold);line(c,[[-18,-29],[-26,-29]],P.metalDark,2);if(command){c.globalAlpha=.4+.2*Math.sin(t*12);for(let i=0;i<3;i++){c.beginPath();c.arc(-28,-29,8+i*7,-.5,.5);c.strokeStyle=P.cream;c.lineWidth=2;c.stroke()}}c.restore();return}
 c.rotate(charge?.23:Math.sin(t*1.9)*.025-(o.hit||0)*.08);c.translate(0,prep?7:Math.abs(walk)*-2);for(const side of [-1,1]){line(c,[[side*14,9],[side*17+side*walk*3,23]],P.clothDark,14);oval(c,side*18+side*walk*3,27,11,6,P.shoe)}shape(c,[[-28,-25],[23,-28],[30,-8],[23,16],[-22,16],[-31,-8]],P.skinShade);oval(c,0,-11,25,23,P.skin);shape(c,[[-26,-21],[-12,-28],[-6,-15],[-20,-9],[-31,-12]],P.bark);shape(c,[[15,-27],[29,-21],[31,-8],[18,-10]],P.metalDark);for(const side of [-1,1]){const swing=walk*3*side,armX=side*(29+(prep?3:0));line(c,[[side*24,-16],[armX,-1+swing],[armX+(charge?-7:prep?-6:0),15+swing]],P.skinShade,17);oval(c,armX+(charge?-7:prep?-6:0),17+swing,12,12,P.skin);line(c,[[armX-6,17+swing],[armX+6,17+swing]],P.skinShade,2);shape(c,[[armX-10,3+swing],[armX+8,3+swing],[armX+10,9+swing],[armX-10,10+swing]],P.wood)}c.save();c.translate(charge?9:0,prep?5:0);oval(c,0,-31,18,16,o.hit>.1?P.hit:P.skin);oval(c,-8,-30,6,8,P.skinShade,false);face(c,1,-34,{blink:blink(t,z.uid),angry:true});shape(c,[[-20,-40],[-14,-49],[17,-47],[20,-40]],P.bark);line(c,[[-13,-44],[12,-44]],P.wood,4);shape(c,[[-7,-21],[7,-21],[4,-16],[-3,-16]],P.cream);c.restore();if(charge)for(let i=0;i<3;i++)line(c,[[-45-i*4,-15+i*13],[-28,-15+i*13]],P.cream,2);c.restore()}
export function drawTelegraph(c,z,T,time){const x=z.x*T,y=z.y*T;if(z.bossId==='collector'&&z.stealState==='telegraph'){const targetX=z.x*T+Math.cos(time*5)*22;c.save();c.globalAlpha=.5+.2*Math.sin(time*14);c.strokeStyle=P.sun;c.lineWidth=2;c.setLineDash([3,5]);c.beginPath();c.arc(x,y,Math.max(28,z.stealRadius*T),0,Math.PI*2);c.stroke();c.setLineDash([]);oval(c,targetX,y-42,4,4,P.sun);c.restore();return}if(z.bossId==='foreman'&&z.commandState==='telegraph'){c.save();c.globalAlpha=.35+.2*Math.sin(time*12);c.strokeStyle=P.cream;c.lineWidth=2;for(let i=0;i<3;i++){c.beginPath();c.arc(x,y,22+i*13,-Math.PI*.82,-Math.PI*.18);c.stroke()}c.fillStyle=P.ink;c.font='bold 11px system-ui';c.textAlign='center';c.fillText('REINFORCEMENTS!',x,y-60);c.restore();return}if(z.chargeState!=='telegraph')return;const dx=z.chargeTargetX*T-x,dy=z.chargeTargetY*T-y,length=Math.hypot(dx,dy);c.save();c.translate(x,y);c.rotate(Math.atan2(dy,dx));c.fillStyle=P.damage;c.globalAlpha=.17;c.fillRect(0,-15,length,30);c.globalAlpha=.95;line(c,[[0,-15],[length,-15]],P.cream,2);line(c,[[0,15],[length,15]],P.cream,2);for(let s=10;s<length;s+=29){const at=s+(time*20)%29;if(at>length)continue;line(c,[[at-6,-7],[at+2,0],[at-6,7]],P.damage,3)}c.restore();c.save();c.fillStyle=P.ink;c.font='bold 12px system-ui';c.textAlign='center';c.fillText('⚠ CHARGE',x,y-57);c.restore()}
